// 若雨中文：目录地址兜底
// 详情页给不出 Index.shtml 链接时，由书籍地址反推 /Html/Book/{id前n-3位}/{id}/Index.shtml
fn yxTocUrl(toc, book, root) {
  let t = str(toc)
  if (t != '') { return t }
  let b = str(book)
  let a = match(b, '/Book/(\d+?)(\d{3})/', 1)
  let c = match(b, '/Book/(\d+?)(\d{3})/', 2)
  if (a == null || c == null) { return b }
  return str(root) + '/Html/Book/' + str(a) + '/' + str(a) + str(c) + '/Index.shtml'
}

// 若雨中文：简介清理
// 站点把换行输出成了字面量 \n（反斜杠+n），这里转成真换行；句末仍按原规则插 <br>
fn yxIntro(s) {
  let t = replace(str(s), '\\\\n', '\n', 'g')
  t = trim(t)
  t = replace(t, '(^|[。！？]+["」）】]?)', m => m[1] + '<br>', 'g')
  return t
}
